def eta(a,b):
 if b<a: return 1-b/a
 if b>a: return 1-(1-b)/(1-a)
 return 0.
for r in [0.1,0.01,0.001]:
 w=[1-r,r]
 before=[r,r]
 after=[r,0.]
 def dcp_binary(probs):
  return min(sum(wi*eta(a,b) for wi,b in zip(w,probs)) for a in [0.,1.]+probs)
 tv=sum(wi*abs(x-y) for wi,x,y in zip(w,before,after))
 print({'r':r,'before_DCP':dcp_binary(before),'after_DCP':dcp_binary(after),'joint_TV':tv,'DCP_over_TV':dcp_binary(after)/tv})
def eta_convex(a,b):
 return a*(a-b) if b<a else (1-a)*(b-a)
u=(0.5,0.1)
v=(0.6,0.3)
m=tuple((x+y)/2 for x,y in zip(u,v))
print({'convexity_points':(u,v),'function_at_midpoint':eta_convex(*m),'average_function_value':(eta_convex(*u)+eta_convex(*v))/2})
PY"
